-- =====================================================================
-- DEPAZ — Migration v5: Historical Certificates Import
-- Run in Supabase SQL Editor (once)
-- =====================================================================

-- ── 1. Add file_url column to council_certificates ─────────────────
ALTER TABLE council_certificates
  ADD COLUMN IF NOT EXISTS file_url TEXT DEFAULT '';

-- ── 2. Insert cert campaigns ───────────────────────────────────────
INSERT INTO council_cert_campaigns (name, type, description)
VALUES
  ('วันครู',                  'activity', 'เกียรติบัตรวันครู'),
  ('จัดการเลือกตั้ง68/69',   'activity', 'เกียรติบัตรจัดการเลือกตั้ง 68/69'),
  ('การเขียนใบโครงการ',       'activity', 'เกียรติบัตรการเขียนใบโครงการ')
ON CONFLICT DO NOTHING;

